'use strict';
const fs   = require('fs');
const path = require('path');

const PROJECT_ROOT = path.resolve(__dirname, '..');
const config = require(path.join(PROJECT_ROOT, 'build.config.cjs'));

// Source files come from the lucide-static npm package – this script is
// lucide-specific. Only the output naming and scan files vary per project.
const LUCIDE_DIR = path.resolve(PROJECT_ROOT, 'node_modules', 'lucide-static', 'font');
const CODEPOINTS = path.join(LUCIDE_DIR, 'codepoints.json');
const SRC_WOFF2  = path.join(LUCIDE_DIR, 'lucide.woff2');

const ic = config.iconFont;
const FONT_DIR    = path.resolve(PROJECT_ROOT, config.fontDir);
const OUT_WOFF2   = path.join(FONT_DIR, ic.outName);
const OUT_SCSS    = path.resolve(PROJECT_ROOT, ic.generatedScssPath);
const URL_IN_SCSS = ic.urlInGeneratedScss;

async function main() {
    const skipSubset = process.env.SKIP_ICON_SUBSET === '1';
    if (skipSubset) {
        console.log('  subset-icons: skipping subset (SKIP_ICON_SUBSET=1), embedding full lucide font');
    }

    const codepoints = JSON.parse(fs.readFileSync(CODEPOINTS, 'utf8'));

    let usedIcons;
    if (skipSubset) {
        usedIcons = new Set(Object.keys(codepoints));
    } else {
        // Scan inputs come from iconFont.scanFiles in build.config.cjs. A CLI
        // override is permitted for ad-hoc testing. Either source may contain glob
        // patterns (*, ?); they are expanded here via fs.globSync (stable since Node 22).
        const cliInputs = process.argv.slice(2);
        const inputs    = cliInputs.length > 0 ? cliInputs : ic.scanFiles;
        if (!inputs || inputs.length === 0) {
            console.error('  iconFont.scanFiles must be a non-empty array in build.config.cjs');
            process.exit(1);
        }

        const expanded = [];
        for (const entry of inputs) {
            if (/[*?]/.test(entry)) {
                expanded.push(...fs.globSync(entry));
            } else {
                expanded.push(entry);
            }
        }

        usedIcons = new Set();
        const literalPattern = /\bicon-([a-z0-9-]+)\b/g;

        for (const file of expanded) {
            if (!fs.existsSync(file)) {
                console.warn(`  skip: ${file} not found`);
                continue;
            }
            const content = fs.readFileSync(file, 'utf8');
            for (const match of content.matchAll(literalPattern)) {
                const name = match[1];
                if (Object.prototype.hasOwnProperty.call(codepoints, name)) {
                    usedIcons.add(name);
                }
            }
        }

        if (usedIcons.size === 0) {
            console.warn('  no lucide icons found in inputs – emitting empty subset');
        }
    }

    fs.mkdirSync(path.dirname(OUT_WOFF2), { recursive: true });

    if (skipSubset) {
        fs.copyFileSync(SRC_WOFF2, OUT_WOFF2);
    } else {
        const codepointList = Array.from(usedIcons)
            .map((name) => codepoints[name])
            .sort((a, b) => a - b);
        const subsetFont   = require('subset-font');
        const srcBuffer    = fs.readFileSync(SRC_WOFF2);
        const subsetText   = codepointList.map((cp) => String.fromCodePoint(cp)).join('');
        // The icons are addressed by codepoint only, never by ligature, so the GSUB table is dead weight
        const subsetBuffer = await subsetFont(srcBuffer, subsetText, { targetFormat: 'woff2', dropTables: ['GSUB'] });
        fs.writeFileSync(OUT_WOFF2, subsetBuffer);
    }

    const sortedIcons = Array.from(usedIcons).sort();
    const rules = sortedIcons
        .map((name) => {
            const hex = codepoints[name].toString(16);
            return `.icon-${name}::before { content: "\\${hex}"; }`;
        })
        .join('\n');

    const scss = `// GENERATED by scripts/subset-icons.js – do not edit.
@font-face {
    font-family: "lucide";
    font-style: normal;
    font-display: swap;
    src: url("${URL_IN_SCSS}") format("woff2");
}

[class^="icon-"],
[class*=" icon-"] {
    font-family: "lucide" !important;
    font-size: inherit;
    font-style: normal;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

${rules}
`;

    fs.writeFileSync(OUT_SCSS, scss);

    const srcSize = fs.statSync(SRC_WOFF2).size;
    const outSize = fs.statSync(OUT_WOFF2).size;
    const pct     = ((outSize / srcSize) * 100).toFixed(1);
    console.log(
        `  lucide: ${usedIcons.size} / ${Object.keys(codepoints).length} icons, ` +
        `${(outSize / 1024).toFixed(1)} KB (${pct}% of ${(srcSize / 1024).toFixed(0)} KB source)`
    );
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});
